import {CHECKED_AT,scheduleMeta,fieldStatusLabel} from './official-schedule.js';
import {sourceHtml,eventSourceHtml,futureHtml} from './schedule-ui.js';
export function renderDetailDates({id,meta,ownEvents,params,key,dateText,formatDate,eventLabel,esc}){
 const verified=scheduleMeta[id],today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const dateRow=e=>`<p class="ed-date-note"><strong>${esc(eventLabel(e))}</strong></p><p class="ed-date-value">${dateText(e)}</p>${e.note?`<p class="ed-date-note">${esc(e.note)}</p>`:''}`;
 const dateCard=type=>{
  const list=ownEvents.filter(e=>e.type===type),upcoming=list.filter(e=>e.date>=today);const shown=list.length>4?(upcoming.length?upcoming.slice(0,3):list.slice(-3)):list;const rest=list.filter(e=>!shown.includes(e));
  let status=verified.fieldSummaries?.[type]||fieldStatusLabel(verified.fields[type]);
  if(verified.fields[type]==='rolling')status=type==='result'?'受検日・受検月ごとに異なります':type==='deadline'?'予約する日時・会場により異なります':'日時・会場を選んで受験';
  return `<article class="ed-date-card ${type}"><h3>${type==='deadline'?'申し込みの締切':type==='exam'?'試験日':meta.resultLabel}</h3>${shown.length?shown.map(dateRow).join(''):`<p class="ed-date-missing">${esc(status)}</p>`}${rest.length?`<details class="ed-more-dates"><summary>ほかの日程も見る（全${list.length}件）</summary>${rest.map(dateRow).join('')}</details>`:''}${verified.fieldNotes?.[type]?`<p class="ed-date-note">${esc(verified.fieldNotes[type])}</p>`:''}${list.length?[...new Set(list.map(e=>e.sourceId))].map(s=>eventSourceHtml(list.find(e=>e.sourceId===s))).join(''):sourceHtml(id,verified.fieldSourceIds?.[type])}</article>`;
 };
 const isUnverified=Object.values(verified.fields).includes('unverified'),hasDates=ownEvents.length>0;
 const application=verified.application?.length||verified.applicationNote?`<div class="ed-application"><h3>申し込みの開始・受付の案内</h3>${(verified.application||[]).map(a=>`<p><strong>${esc(a.label)}</strong>　${a.start?formatDate(a.start,true):''}${a.time?' '+a.time:''}${a.start?'から':''}</p>`).join('')}${verified.applicationNote?`<p>${esc(verified.applicationNote)}</p>`:''}</div>`:'';
 const availability=verified.availability?`<section class="ed-availability"><h3>受ける日時を予約する試験です</h3><p>${esc(verified.availability.note)}</p>${verified.availability.suspensions?.length?`<h4>公表されている休止期間</h4><ul>${verified.availability.suspensions.map(s=>`<li><strong>${formatDate(s.start,true)}から${s.end?formatDate(s.end,true)+'まで':'（終了の具体日は未発表）'}</strong><p>${esc(s.note||'')}</p></li>`).join('')}</ul>`:''}${verified.examWindows?.length?`<details><summary>月ごとの実施期間・結果発表日を見る</summary><div class="ed-window-table tablewrap"><table><thead><tr><th>予約できる実施期間</th><th>結果発表</th></tr></thead><tbody>${verified.examWindows.map(w=>`<tr><td>${formatDate(w.start,true)}〜${formatDate(w.end,true)}</td><td>${w.result?formatDate(w.result,true):'公式案内で確認'}</td></tr>`).join('')}</tbody></table></div></details>`:''}${sourceHtml(id)}</section>`:'';
 return `<section class="ed-dates" id="${key('dates')}" aria-labelledby="${key('dates-title')}"><div class="ed-section-title"><div><span class="ed-kicker">まずは、日程を確認</span><h2 id="${key('dates-title')}">受ける日と、申し込みの期限</h2></div><span class="ed-sample-tag">${isUnverified?'確認できた情報のみ掲載':hasDates?'公式情報を確認済み':'公表状況・受験方式をご案内'}</span></div><p class="small-note">掲載対象：${esc(verified.scope)} ／ 確認日：${(verified.checkedAt||CHECKED_AT).replaceAll('-','/')}（時刻は日本時間）</p>${meta.status?`<p class="ed-status">${meta.status}。次年度の日程とは別です。</p>`:''}<div class="ed-date-cards">${['deadline','exam','result'].map(dateCard).join('')}</div>${application}${availability}<p class="ed-disclaimer">${esc(verified.notes||'')}</p>${futureHtml(id)}${ownEvents.length?`<details class="ed-date-tools"><summary>日程をカレンダーに表示・予定ファイルを保存する</summary><div>${ownEvents.map(e=>`<article class="ed-date-row" ${params.get('event')===e.id?'data-highlight="true"':''}><div><span class="event-type ${e.type==='deadline'?'peach':e.type==='exam'?'mint':'lavender'}">${esc(eventLabel(e))}</span><strong>${dateText(e)}</strong>${e.note?`<small>${esc(e.note)}</small>`:''}${eventSourceHtml(e)}</div><div><button class="quiet-button" data-calendar-event="${e.id}">カレンダーに表示</button><button class="text-button" data-ics="${e.id}">予定ファイルを保存</button></div></article>`).join('')}</div><p class="small-note">予定ファイルには出典と確認日も添えています。申し込みや通知の予約は行われません。</p></details>`:''}</section>`;
}
